"""ConvApparel §4 validation statistics and a deliberately non-LLM CPU baseline.

PLSA means population-level statistical alignment, not latent semantic analysis.
The small logistic discriminator below is a diagnostic baseline, not the paper's
fine-tuned Gemini HLS model. Real HLS can be supplied through the same scorer API.
"""

from __future__ import annotations

import itertools
import math
import random
import re
from bisect import bisect_left, bisect_right
from collections import Counter
from dataclasses import dataclass
from statistics import mean
from typing import Callable, Sequence


@dataclass(frozen=True)
class Conversation:
    session_id: str
    participant_id: str
    policy: str
    user_turns: tuple[str, ...]
    is_human: bool
    # Annotation values come from human raters or an independently validated judge.
    # They are not inferred from keywords by the validation component.
    annotations: tuple[tuple[str, float], ...] = ()
    simulator_training_sessions: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if not self.session_id or not self.participant_id or not self.policy:
            raise ValueError("session, participant and policy IDs are required")
        if type(self.is_human) is not bool:
            raise ValueError("is_human must be an explicit boolean")
        if not self.user_turns or any(not text.strip() for text in self.user_turns):
            raise ValueError("at least one nonempty user turn is required")
        if len(dict(self.annotations)) != len(self.annotations):
            raise ValueError("duplicate annotation name")
        if any(not math.isfinite(value) for _, value in self.annotations):
            raise ValueError("annotations must be finite")


@dataclass(frozen=True)
class DiscriminatorView:
    """No source class, policy, participant identity or rating reaches D(c)."""

    user_turns: tuple[str, ...]


def behavior_metrics(conversation: Conversation) -> dict[str, float]:
    """Basic §4.1 statistics plus externally provided dialog-act/experience rates."""
    result = {
        "turns_per_session": float(len(conversation.user_turns)),
        "words_per_user_turn": mean(len(turn.split()) for turn in conversation.user_turns),
    }
    if set(result).intersection(dict(conversation.annotations)):
        raise ValueError("annotations cannot overwrite computed basic statistics")
    result.update(conversation.annotations)
    return result


def _finite(values: Sequence[float]) -> tuple[float, ...]:
    result = tuple(float(value) for value in values)
    if not result or any(not math.isfinite(value) for value in result):
        raise ValueError("samples must be nonempty and finite")
    return result


def ks_statistic(first: Sequence[float], second: Sequence[float]) -> float:
    """Two-sided empirical KS distance, with ties evaluated at each jump."""
    a, b = _finite(first), _finite(second)
    a, b = sorted(a), sorted(b)
    return max(abs(bisect_right(a, point) / len(a) - bisect_right(b, point) / len(b)) for point in sorted(set(a + b)))


def mann_whitney_u(first: Sequence[float], second: Sequence[float]) -> float:
    """U for the first sample; average ranks are equivalent to half credit on ties."""
    a, b = _finite(first), _finite(second)
    ordered = sorted(b)
    return sum(bisect_left(ordered, x) + 0.5 * (bisect_right(ordered, x) - bisect_left(ordered, x)) for x in a)


def alignment_test(
    human: Sequence[float],
    simulated: Sequence[float],
    *,
    permutations: int = 999,
    exact_limit: int = 20_000,
    seed: int = 42,
) -> dict[str, float | int | str]:
    """KS and MWU with exact small-sample or seeded permutation p-values.

    This avoids asymptotic tie assumptions. Monte Carlo p-values use the +1
    correction. Neither a high p-value nor a small distance proves equivalence.
    """
    a, b = _finite(human), _finite(simulated)
    if permutations < 1 or exact_limit < 1:
        raise ValueError("positive permutation budgets required")
    pooled, n = a + b, len(a)
    ks = ks_statistic(a, b)
    u = mann_whitney_u(a, b)
    centered_u = abs(u - len(a) * len(b) / 2)
    combinations = math.comb(len(pooled), n)
    exact = combinations <= exact_limit
    rng = random.Random(seed)
    groups = (
        itertools.combinations(range(len(pooled)), n)
        if exact
        else (rng.sample(range(len(pooled)), n) for _ in range(permutations))
    )
    ks_extreme = u_extreme = total = 0
    for indices in groups:
        chosen = set(indices)
        left = [pooled[i] for i in range(len(pooled)) if i in chosen]
        right = [pooled[i] for i in range(len(pooled)) if i not in chosen]
        ks_extreme += ks_statistic(left, right) >= ks - 1e-12
        u_extreme += abs(mann_whitney_u(left, right) - len(a) * len(b) / 2) >= centered_u - 1e-12
        total += 1
    correction = 0 if exact else 1
    return {
        "human_mean": mean(a),
        "simulated_mean": mean(b),
        "ks": ks,
        "ks_pvalue": (ks_extreme + correction) / (total + correction),
        "mann_whitney_u": u,
        "mwu_pvalue": (u_extreme + correction) / (total + correction),
        "pvalue_method": "exact_permutation" if exact else "monte_carlo_permutation",
        "permutations": total,
    }


def plsa(
    human: Sequence[Conversation], simulated: Sequence[Conversation], *, seed: int = 42
) -> dict[str, dict[str, float | int | str]]:
    """Compare the same explicitly annotated metric in each population."""
    if not human or not simulated or any(not c.is_human for c in human) or any(c.is_human for c in simulated):
        raise ValueError("separate nonempty human and simulated populations required")
    metrics = [behavior_metrics(c) for c in (*human, *simulated)]
    keys = set(metrics[0])
    if any(set(row) != keys for row in metrics):
        raise ValueError("all conversations must use the same annotation schema")
    return {
        key: alignment_test(
            [row[key] for row in metrics[: len(human)]],
            [row[key] for row in metrics[len(human) :]],
            seed=seed,
        )
        for key in sorted(keys)
    }


def assert_split_disjoint(train: Sequence[Conversation], heldout: Sequence[Conversation]) -> None:
    """Participant/session-level separation, not a random split of user turns."""
    for name in ("session_id", "participant_id"):
        if {getattr(c, name) for c in train}.intersection(getattr(c, name) for c in heldout):
            raise ValueError(f"train/heldout {name} leakage")
    ids = [c.session_id for c in (*train, *heldout)]
    if len(ids) != len(set(ids)):
        raise ValueError("duplicate conversation session")


@dataclass(frozen=True)
class LogisticHumanDiscriminator:
    """Actually trained bag-of-words diagnostic; never advertised as Gemini HLS."""

    vocabulary: tuple[str, ...]
    weights: tuple[float, ...]
    bias: float
    training_sessions: frozenset[str]
    training_participants: frozenset[str]
    training_policies: frozenset[str]

    @staticmethod
    def tokens(conversation: Conversation | DiscriminatorView) -> Counter[str]:
        tokens = re.findall(r"\w+", " ".join(conversation.user_turns).lower())
        return Counter(tokens + [f"{left} {right}" for left, right in zip(tokens, tokens[1:])])

    def __call__(self, conversation: DiscriminatorView) -> float:
        counts = self.tokens(conversation)
        norm = max(1, sum(counts.values()))
        logit = self.bias + sum(weight * counts[token] / norm for token, weight in zip(self.vocabulary, self.weights, strict=True))
        return 1.0 / (1.0 + math.exp(-max(-40.0, min(40.0, logit))))


def train_logistic_discriminator(
    train: Sequence[Conversation], *, epochs: int = 200, learning_rate: float = 0.5, l2: float = 0.001
) -> LogisticHumanDiscriminator:
    """CPU diagnostic BCE optimization. Only training labels enter this routine."""
    if not train or {c.is_human for c in train} != {True, False}:
        raise ValueError("both human and simulated training classes required")
    if not 1 <= epochs <= 400 or not math.isfinite(learning_rate) or learning_rate <= 0 or not math.isfinite(l2) or l2 < 0:
        raise ValueError("invalid optimization budget")
    if len(train) > 256 or any(sum(len(turn.split()) for turn in c.user_turns) > 4096 for c in train):
        raise ValueError("CPU diagnostic training budget exceeds 256 conversations or 4096 words per conversation")
    if len({c.session_id for c in train}) != len(train):
        raise ValueError("duplicate training sessions")
    vocabulary = tuple(sorted({word for c in train for word in LogisticHumanDiscriminator.tokens(c)}))
    if len(vocabulary) > 4096:
        raise ValueError("CPU diagnostic vocabulary exceeds 4096 features; no automatic truncation")
    features = []
    for conversation in train:
        counts = LogisticHumanDiscriminator.tokens(conversation)
        norm = max(1, sum(counts.values()))
        features.append(tuple(counts[token] / norm for token in vocabulary))
    weights, bias = [0.0] * len(vocabulary), 0.0
    # Class balancing prevents the paper's different human/simulator counts from
    # becoming an unspoken source prior in this diagnostic baseline.
    counts_by_class = Counter(c.is_human for c in train)
    for _ in range(epochs):
        gradient, bias_gradient = [0.0] * len(vocabulary), 0.0
        for conversation, row in zip(train, features, strict=True):
            logit = bias + sum(w * x for w, x in zip(weights, row, strict=True))
            prediction = 1 / (1 + math.exp(-max(-40.0, min(40.0, logit))))
            error = (prediction - float(conversation.is_human)) / (2 * counts_by_class[conversation.is_human])
            bias_gradient += error
            for index, value in enumerate(row):
                gradient[index] += error * value
        weights = [w - learning_rate * (g + l2 * w) for w, g in zip(weights, gradient, strict=True)]
        bias -= learning_rate * bias_gradient
    return LogisticHumanDiscriminator(
        vocabulary, tuple(weights), bias,
        frozenset(c.session_id for c in train),
        frozenset(c.participant_id for c in train),
        frozenset(c.policy for c in train),
    )


def evaluate_hls(
    heldout: Sequence[Conversation], scorer: Callable[[DiscriminatorView], float]
) -> dict[str, float | int]:
    """Mean D(c), heldout classifier accuracy and Brier score are separate facts."""
    if not heldout or {c.is_human for c in heldout} != {True, False}:
        raise ValueError("both heldout classes required to validate a discriminator")
    if isinstance(scorer, LogisticHumanDiscriminator):
        if scorer.training_sessions.intersection(c.session_id for c in heldout) or scorer.training_participants.intersection(c.participant_id for c in heldout):
            raise ValueError("discriminator evaluated on training identity")
    predictions = [float(scorer(DiscriminatorView(c.user_turns))) for c in heldout]
    if any(not math.isfinite(p) or not 0 <= p <= 1 for p in predictions):
        raise ValueError("D(c) must be a finite human probability")
    return {
        "conversations": len(heldout),
        "simulated_hls": mean(p for c, p in zip(heldout, predictions, strict=True) if not c.is_human),
        "human_hls": mean(p for c, p in zip(heldout, predictions, strict=True) if c.is_human),
        "discriminator_accuracy": mean((p >= 0.5) == c.is_human for c, p in zip(heldout, predictions, strict=True)),
        "brier_score": mean((p - c.is_human) ** 2 for c, p in zip(heldout, predictions, strict=True)),
    }


def counterfactual_validation(
    simulator_training: Sequence[Conversation], heldout: Sequence[Conversation],
    scorer: Callable[[DiscriminatorView], float], *, training_policy: str, target_policy: str,
    seed: int = 42,
) -> dict:
    """Validate supplied OOD simulator traces, not train or generate a simulator.

    The simulator's human training manifest is distinct from the discriminator
    training corpus. Generated traces must declare the source training sessions;
    this is a provenance contract, not proof of a remote simulator's behavior.
    """
    if training_policy == target_policy or not simulator_training or {c.policy for c in simulator_training} != {training_policy} or any(not c.is_human for c in simulator_training):
        raise ValueError("simulator training must contain only human source-policy data")
    assert_split_disjoint(simulator_training, heldout)
    if not heldout or {c.policy for c in heldout} != {target_policy}:
        raise ValueError("heldout data must contain only the unseen target policy")
    expected_sessions = frozenset(c.session_id for c in simulator_training)
    if any(frozenset(c.simulator_training_sessions) != expected_sessions for c in heldout if not c.is_human):
        raise ValueError("simulated trace has missing/mismatched simulator training provenance")
    return {
        "training_policy": training_policy, "target_policy": target_policy,
        "simulator_training_provenance": "declared_manifest_not_independently_certified",
        "plsa": plsa([c for c in heldout if c.is_human], [c for c in heldout if not c.is_human], seed=seed),
        "hls": evaluate_hls(heldout, scorer),
        "diagnostic_only": True,
        "discriminator_backend": "cpu_bag_of_words_logistic_not_paper_gemini" if isinstance(scorer, LogisticHumanDiscriminator) else "external_scorer_requires_independent_validation",
    }

"""ScientistOne CoE's deterministic audit core, not an autonomous scientist.

Implements hash-linked numerical provenance, canonical evaluator reruns, adaptive
noise tolerance, and independent audit verdict aggregation. Semantic/citation
checks without external evidence remain unverified, never default to passed.
"""

from __future__ import annotations

import hashlib
import json
import math
from dataclasses import dataclass
from statistics import mean, pstdev
from typing import Callable, Mapping, Sequence


@dataclass(frozen=True)
class Artifact:
    key: str
    sha256: str
    kind: str

    def __post_init__(self) -> None:
        if not self.key or not self.kind or len(self.sha256) != 64:
            raise ValueError("artifact requires a key, kind and SHA256 digest")
        try:
            int(self.sha256, 16)
        except ValueError as error:
            raise ValueError("invalid SHA256 digest") from error

    @classmethod
    def from_bytes(cls, key: str, payload: bytes, kind: str) -> Artifact:
        return cls(key, hashlib.sha256(payload).hexdigest(), kind)


@dataclass(frozen=True)
class Measurement:
    artifact: str
    metric: str
    value: float
    stage: str
    unit: str
    direction: str

    def __post_init__(self) -> None:
        if not math.isfinite(self.value) or self.direction not in {"min", "max"}:
            raise ValueError("finite value and explicit metric direction required")
        if not all((self.artifact, self.metric, self.stage, self.unit)):
            raise ValueError("measurement provenance fields required")


@dataclass(frozen=True)
class Claim:
    key: str
    kind: str
    supports: tuple[str, ...]
    metric: str | None = None
    value: float | None = None
    stage: str | None = None
    unit: str | None = None
    direction: str | None = None

    def __post_init__(self) -> None:
        if not self.key or self.kind not in {"numerical", "citation", "method", "conclusion"}:
            raise ValueError("invalid claim key/type")
        if self.kind == "numerical":
            if self.value is None or not math.isfinite(self.value):
                raise ValueError("numerical claim requires a finite value")
            if not all((self.metric, self.stage, self.unit)) or self.direction not in {"min", "max"}:
                raise ValueError("numerical metric, stage, unit and direction required")


def verify_bundle(
    artifacts: Sequence[Artifact], claims: Sequence[Claim], payloads: Mapping[str, bytes]
) -> dict:
    """Verify source bytes and a DAG from every claim to at least one artifact.

    Structural provenance is not logical or semantic entailment. Missing bytes,
    dangling nodes, cycles and a claim with no grounding source all fail closed.
    """
    artifact_map = {artifact.key: artifact for artifact in artifacts}
    claim_map = {claim.key: claim for claim in claims}
    if len(artifact_map) != len(artifacts) or len(claim_map) != len(claims) or set(artifact_map) & set(claim_map):
        raise ValueError("artifact/claim IDs must be unique and disjoint")
    hash_valid = {
        key: key in payloads and hashlib.sha256(payloads[key]).hexdigest() == artifact.sha256
        for key, artifact in artifact_map.items()
    }

    def grounded(key: str, active: frozenset[str]) -> bool:
        if key in active:
            return False
        if key in artifact_map:
            return hash_valid[key]
        if key not in claim_map:
            return False
        claim = claim_map[key]
        return bool(claim.supports) and all(grounded(child, active | {key}) for child in claim.supports)

    return {
        "artifact_hash_valid": hash_valid,
        "structurally_grounded": {claim.key: grounded(claim.key, frozenset()) for claim in claims},
        "semantic_entailment": "unverified",
    }


def score_verification(
    reported: Measurement,
    *, solution: Artifact, solution_bytes: bytes, evaluator: Artifact,
    evaluator_bytes: bytes,
    evaluate: Callable[[bytes, bytes, int], Measurement],
    repeats: int = 5,
) -> dict:
    """I1 canonical evaluator reruns, not a supplied list of claimed scores.

    The evaluator callback is caller-audited trusted code. No arbitrary source is
    executed by this module. The same solution/evaluator bytes are used each run.
    """
    if repeats != 5:
        raise ValueError("paper I1 protocol requires five evaluator reruns")
    for artifact, payload in ((solution, solution_bytes), (evaluator, evaluator_bytes)):
        if hashlib.sha256(payload).hexdigest() != artifact.sha256:
            raise ValueError("canonical evaluator/solution hash mismatch")
    runs = [evaluate(solution_bytes, evaluator_bytes, index) for index in range(repeats)]
    signature = (reported.metric, reported.stage, reported.unit, reported.direction)
    if any((run.metric, run.stage, run.unit, run.direction) != signature for run in runs):
        return {"status": "mismatch", "reason": "metric_stage_unit_or_direction_mismatch", "reruns": repeats}
    values = [run.value for run in runs]
    average, sigma = mean(values), pstdev(values)
    absolute_tolerance = max(0.01 * abs(average), 3 * sigma)
    # At a deterministic zero mean the relative formula is undefined. Require
    # exact zero rather than inventing a permissive epsilon tolerance.
    difference = abs(reported.value - average)
    return {
        "status": "match" if difference <= absolute_tolerance else "mismatch",
        "reruns": repeats,
        "canonical_mean": average,
        "canonical_population_std": sigma,
        "absolute_tolerance": absolute_tolerance,
        "relative_tolerance": absolute_tolerance / abs(average) if average else None,
        "absolute_difference": difference,
        "solution_sha256": solution.sha256,
        "evaluator_sha256": evaluator.sha256,
    }


def numerical_cpr(
    claims: Sequence[Claim], measurements: Sequence[Measurement],
    artifacts: Sequence[Artifact], payloads: Mapping[str, bytes], *, atol: float = 1e-12,
) -> dict:
    """Numerical CPR counts matching log entries, not merely a source hyperlink.

    The artifact referenced by a measurement must be a valid execution log. The
    same metric/stage/unit/direction must appear in the declared support chain.
    """
    if not math.isfinite(atol) or atol < 0:
        raise ValueError("finite nonnegative matching tolerance required")
    structural = verify_bundle(artifacts, claims, payloads)
    artifact_map = {artifact.key: artifact for artifact in artifacts}
    # A caller-supplied Measurement is not evidence unless its complete record
    # is actually present in the verified log bytes. No numeric claims are
    # accepted merely because their metadata points at a real, unrelated file.
    logged = set()
    for artifact in artifacts:
        if artifact.kind != "execution_log" or not structural["artifact_hash_valid"][artifact.key]:
            continue
        try:
            document = json.loads(payloads[artifact.key])
            for record in document["measurements"]:
                logged.add(Measurement(artifact=artifact.key, **record))
        except (KeyError, TypeError, ValueError, json.JSONDecodeError) as error:
            raise ValueError("execution log must contain canonical measurement records") from error
    if any(measurement not in logged for measurement in measurements):
        raise ValueError("measurement is not present in verified execution-log bytes")
    claim_map = {claim.key: claim for claim in claims}
    matched = {}

    def supports(key: str, seen: frozenset[str]) -> set[str]:
        if key in seen:
            return set()
        if key in artifact_map:
            return {key}
        if key not in claim_map:
            return set()
        return set().union(*(supports(child, seen | {key}) for child in claim_map[key].supports))

    for claim in claims:
        if claim.kind != "numerical":
            continue
        sources = supports(claim.key, frozenset())
        matched[claim.key] = structural["structurally_grounded"][claim.key] and any(
            measurement.artifact in sources
            and artifact_map[measurement.artifact].kind == "execution_log"
            and (measurement.metric, measurement.stage, measurement.unit, measurement.direction)
            == (claim.metric, claim.stage, claim.unit, claim.direction)
            and math.isclose(measurement.value, claim.value, rel_tol=0.0, abs_tol=atol)
            for measurement in measurements
        )
    return {
        "quantitative_claims": len(matched), "matched_claims": sum(matched.values()),
        "cpr": sum(matched.values()) / len(matched) if matched else None,
        "claims": matched,
        "semantic_support_verified": False,
    }


@dataclass(frozen=True)
class AuditVote:
    verdict: str
    evidence: str
    judge_id: str


def majority_audit(votes: Sequence[AuditVote], *, pass_verdict: str, fail_verdict: str) -> dict:
    """I2/I4 independent judgment aggregation with abstentions and evidence IDs."""
    if pass_verdict == fail_verdict:
        raise ValueError("pass/fail must differ")
    if not votes:
        return {"status": "unverified", "reason": "no_external_judgments", "votes": 0}
    if len({vote.judge_id for vote in votes}) != len(votes):
        raise ValueError("each judgment needs a distinct invocation ID")
    allowed = {pass_verdict, fail_verdict, "unverified"}
    if any(vote.verdict not in allowed or not vote.judge_id or not vote.evidence.strip() for vote in votes):
        raise ValueError("invalid or ungrounded audit vote")
    threshold = len(votes) // 2 + 1
    counts = {name: sum(vote.verdict == name for vote in votes) for name in allowed}
    status = next((name for name in (pass_verdict, fail_verdict) if counts[name] >= threshold), "unverified")
    return {"status": status, "votes": len(votes), "counts": counts, "threshold": threshold}


def reference_verification(
    *, reference_id: str, resolve: Callable[[str], Sequence[Mapping[str, str]]] | None,
    disambiguate: Callable[[str, tuple[Mapping[str, str], ...]], AuditVote] | None,
) -> dict:
    """I3 requires actual resolver + semantic disambiguation, not URL existence.

    No results is unverified here: without proof of completed independent source
    queries it is not justified to label a citation hallucinated.
    """
    if resolve is None or disambiguate is None:
        return {"status": "unverified", "reason": "resolver_or_disambiguator_unavailable"}
    records = tuple(resolve(reference_id))
    if not records:
        return {"status": "unverified", "reason": "no_resolver_records_not_a_proof_of_absence"}
    if any(not record.get("source_url", "").startswith("https://") for record in records):
        raise ValueError("resolver records require source URLs")
    vote = disambiguate(reference_id, records)
    if vote.verdict not in {"verified", "hallucinated", "unverified"} or not vote.evidence.strip():
        raise ValueError("grounded disambiguation verdict required")
    return {"status": vote.verdict, "evidence": vote.evidence, "records": len(records)}

"""Bounded Simula taxonomy/generation/critic and complexity calibration protocol.

All semantic operations are external model callbacks; no keyword heuristic is
silently substituted for reasoning. Fixed callbacks in unit demos are L0 only.
"""

from __future__ import annotations

import hashlib
import itertools
import json
import math
import random
from dataclasses import dataclass, field
from statistics import mean
from typing import Callable, Mapping, Sequence


@dataclass
class CallBudget:
    max_calls: int = 100
    trace: list[dict] = field(default_factory=list)

    def call(self, role: str, callback: Callable, *args):
        if self.max_calls < 1 or len(self.trace) >= self.max_calls:
            raise RuntimeError("Simula model-call budget exhausted")
        digest = hashlib.sha256(json.dumps(args, ensure_ascii=False, sort_keys=True, default=str).encode()).hexdigest()
        record = {"role": role, "input_sha256": digest, "status": "started"}
        self.trace.append(record)
        try:
            result = callback(*args)
        except Exception as error:
            record.update(status="failed", error_type=type(error).__name__)
            raise
        record.update(status="completed", output_sha256=hashlib.sha256(json.dumps(result, ensure_ascii=False, sort_keys=True, default=str).encode()).hexdigest())
        return result


@dataclass(frozen=True)
class NodeContext:
    instructions: str
    path: tuple[str, ...]
    siblings: tuple[str, ...]
    plan: str


@dataclass(frozen=True)
class Taxonomy:
    factor: str
    # Paths include their factor root. A tree uses unique paths, not globally
    # unique labels: repeated labels in different branches are permissible.
    leaves: tuple[tuple[str, ...], ...]

    def __post_init__(self) -> None:
        if not self.factor or not self.leaves or len(set(self.leaves)) != len(self.leaves):
            raise ValueError("nonempty taxonomy and unique leaf paths required")
        if any(not path or path[0] != self.factor or any(not part.strip() for part in path) for path in self.leaves):
            raise ValueError("taxonomy paths must start at their factor")
        if any(left != right and right[: len(left)] == left for left in self.leaves for right in self.leaves):
            raise ValueError("a leaf cannot also be an ancestor of another leaf")


@dataclass(frozen=True)
class TaxonomyModels:
    factors: Callable[[str], Sequence[str]]
    propose: Callable[[NodeContext], Sequence[str]]
    critic: Callable[[NodeContext, tuple[str, ...]], Sequence[str]]
    plan: Callable[[str, tuple[tuple[str, ...], ...]], str]


def build_taxonomies(
    instructions: str, models: TaxonomyModels, budget: CallBudget,
    *, depth: int = 2, proposals: int = 2, max_children: int = 8, max_nodes: int = 64,
) -> tuple[Taxonomy, ...]:
    """Appendix B.4: breadth-first best-of-N, independent critic, per-level plan."""
    if not instructions.strip() or not 1 <= depth <= 4 or not 1 <= proposals <= 4:
        raise ValueError("bounded nonempty taxonomy request required")
    if not 1 <= max_children <= 16 or max_nodes < 1:
        raise ValueError("positive tree budgets required")
    factors = tuple(budget.call("factor_identification", models.factors, instructions))
    if not factors or len(set(factors)) != len(factors) or any(not factor.strip() for factor in factors):
        raise ValueError("model must return unique nonempty factors")
    total_nodes, taxonomies = len(factors), []
    if total_nodes > max_nodes:
        raise ValueError("factor list exceeds node budget")
    for factor in factors:
        frontier = ((factor,),)
        plan = f"Expand the factor {factor} under the supplied instructions."
        for level in range(depth):
            next_frontier = []
            for path in frontier:
                siblings = tuple(other[-1] for other in frontier if other[:-1] == path[:-1] and other != path)
                context = NodeContext(instructions, path, siblings, plan)
                raw = tuple(dict.fromkeys(child for _ in range(proposals) for child in budget.call("taxonomy_proposal", models.propose, context)))
                refined = tuple(budget.call("taxonomy_critic", models.critic, context, raw))
                if not refined or len(refined) > max_children or len(set(refined)) != len(refined) or any(not child.strip() for child in refined):
                    raise ValueError("critic returned invalid/budget-exceeding children")
                total_nodes += len(refined)
                if total_nodes > max_nodes:
                    raise ValueError("taxonomy node budget exceeded")
                next_frontier.extend((*path, child) for child in refined)
            frontier = tuple(next_frontier)
            if level + 1 < depth:
                plan = budget.call("taxonomy_level_plan", models.plan, instructions, frontier)
                if not isinstance(plan, str) or not plan.strip():
                    raise ValueError("model level plan must be nonempty")
        taxonomies.append(Taxonomy(factor, frontier))
    return tuple(taxonomies)


@dataclass(frozen=True)
class Strategy:
    name: str
    factors: tuple[str, ...]
    weight: float


@dataclass(frozen=True)
class Critique:
    accepted: bool
    explanation: str


@dataclass(frozen=True)
class GenerationModels:
    strategies: Callable[[str, tuple[Taxonomy, ...]], Sequence[Strategy]]
    scenarios: Callable[[str, tuple[tuple[str, ...], ...], int], Sequence[str]]
    complexify: Callable[[str], str]
    generate: Callable[[str], str]
    requirements_critic: Callable[[str, str], Critique]
    refine: Callable[[str, str, str], str]
    # Both independent prompts are required for correctness-bearing tasks.
    # Their calls receive only the sample; never the other critic's verdict.
    correctness_critic: Callable[[str], Critique] | None = None
    incorrectness_critic: Callable[[str], Critique] | None = None


def generate_dataset(
    instructions: str, taxonomies: tuple[Taxonomy, ...], models: GenerationModels,
    budget: CallBudget, *, size: int = 4, seed: int = 42,
    complexity_ratio: float = 0.5, scenarios_per_mix: int = 2,
    max_attempts: int = 12, max_refinements: int = 1,
    correctness_required: bool = True,
) -> dict:
    """Appendix C plus §2.2 independent double-critic rejection sampling.

    Returns a partial dataset with an explicit budget-exhausted status if target
    size is unreachable; a bounded local run never loops indefinitely to N.
    """
    if not 1 <= size <= 128 or not 0 <= complexity_ratio <= 1 or not 1 <= scenarios_per_mix <= 8:
        raise ValueError("invalid generation budget")
    if max_attempts < 1 or not 0 <= max_refinements <= 3:
        raise ValueError("invalid retry budget")
    if correctness_required and (models.correctness_critic is None or models.incorrectness_critic is None):
        raise ValueError("independent correctness and incorrectness callbacks required")
    taxonomy_map = {taxonomy.factor: taxonomy for taxonomy in taxonomies}
    if not taxonomy_map or len(taxonomy_map) != len(taxonomies):
        raise ValueError("nonempty unique factors required")
    strategies = tuple(budget.call("sampling_strategy", models.strategies, instructions, taxonomies))
    if not strategies or any(not strategy.factors or len(set(strategy.factors)) != len(strategy.factors) or not math.isfinite(strategy.weight) or strategy.weight <= 0 or set(strategy.factors) - set(taxonomy_map) for strategy in strategies):
        raise ValueError("model strategy must select existing compatible factors with positive weights")
    rng, accepted, attempts = random.Random(seed), [], []
    seen = set()
    for _ in range(max_attempts):
        if len(accepted) >= size:
            break
        try:
            strategy = rng.choices(strategies, weights=[strategy.weight for strategy in strategies], k=1)[0]
            mix = tuple(rng.choice(taxonomy_map[factor].leaves) for factor in strategy.factors)
            scenarios = tuple(budget.call("meta_prompt_generation", models.scenarios, instructions, mix, scenarios_per_mix))
            if len(scenarios) != scenarios_per_mix or any(not scenario.strip() for scenario in scenarios):
                raise ValueError("model must return the requested nonempty scenario count")
            meta = rng.choice(scenarios)
            complexified = rng.random() < complexity_ratio
            if complexified:
                meta = budget.call("complexification", models.complexify, meta)
            if not isinstance(meta, str) or not meta.strip():
                raise ValueError("invalid meta prompt")
            sample = budget.call("sample_generation", models.generate, meta)
            valid, explanations = False, []
            for refinement in range(max_refinements + 1):
                if not isinstance(sample, str) or not sample.strip():
                    raise ValueError("generated sample must be nonempty")
                critique = budget.call("requirements_critic", models.requirements_critic, meta, sample)
                if not isinstance(critique, Critique) or type(critique.accepted) is not bool:
                    raise ValueError("critic must return a binary Critique")
                explanations.append(critique.explanation)
                if critique.accepted:
                    valid = True
                    break
                if refinement < max_refinements:
                    sample = budget.call("critic_refinement", models.refine, meta, sample, critique.explanation)
            double = []
            if valid and correctness_required:
                correct = budget.call("independent_correctness_critic", models.correctness_critic, sample)
                incorrect = budget.call("independent_incorrectness_critic", models.incorrectness_critic, sample)
                if not all(isinstance(vote, Critique) and type(vote.accepted) is bool for vote in (correct, incorrect)):
                    raise ValueError("double critics must return binary Critiques")
                # accepted means affirmation of each role's own proposition:
                # 'correct' must be true and 'incorrect' must be false.
                valid = correct.accepted and not incorrect.accepted
                double = [correct.__dict__, incorrect.__dict__]
            digest = hashlib.sha256(sample.encode()).hexdigest()
            duplicate = digest in seen
            record = {"strategy": strategy.name, "mix": mix, "meta_prompt": meta, "complexified": complexified, "sample": sample, "accepted": valid and not duplicate, "duplicate": duplicate, "requirements_explanations": explanations, "double_critic": double}
            attempts.append(record)
            if record["accepted"]:
                seen.add(digest)
                accepted.append(record)
        except RuntimeError as error:
            if str(error) != "Simula model-call budget exhausted":
                raise
            return {"status": "call_budget_exhausted", "samples": accepted, "attempts": attempts, "requested": size, "calls": len(budget.trace)}
    return {"status": "complete" if len(accepted) == size else "attempt_budget_exhausted", "samples": accepted, "attempts": attempts, "requested": size, "calls": len(budget.trace)}


def calibrated_complexity(
    samples: Mapping[str, str], score_batch: Callable[[tuple[tuple[str, str], ...], str], Mapping[str, float]],
    budget: CallBudget, *, guidance: str, appearances: int = 3, batch_size: int = 5,
    seed: int = 42, elo_k: float = 32.0,
) -> dict:
    """Appendix E.3: varied batch scores -> within-batch pairs -> global Elo.

    The paper does not fix Elo's numerical hyperparameters. We declare local
    initial rating 1000, scale 400, K=32 and seeded pair order in the output.
    """
    if not samples or not 1 <= appearances <= 20 or not 2 <= batch_size <= 32 or elo_k <= 0:
        raise ValueError("nonempty samples and bounded calibration budget required")
    if len(samples) < 2 or batch_size > len(samples):
        raise ValueError("at least two samples and batch_size <= dataset size required")
    rng = random.Random(seed)
    ids, schedule = list(samples), []
    # Every round visits every ID once, so each item appears exactly K times.
    for _ in range(appearances):
        rng.shuffle(ids)
        batches = [ids[i : i + batch_size] for i in range(0, len(ids), batch_size)]
        schedule.extend(tuple(batch) for batch in batches)
    scores = {key: [] for key in samples}
    comparisons = []
    for batch in schedule:
        values = dict(budget.call("batch_relative_complexity", score_batch, tuple((key, samples[key]) for key in batch), guidance))
        if set(values) != set(batch) or any(not math.isfinite(value) for value in values.values()):
            raise ValueError("batch scorer must return each requested finite score exactly once")
        for key in batch:
            scores[key].append(float(values[key]))
        for left, right in itertools.combinations(batch, 2):
            comparisons.append((left, right, 1.0 if values[left] > values[right] else 0.0 if values[left] < values[right] else 0.5))
    rng.shuffle(comparisons)
    ratings = {key: 1000.0 for key in samples}
    for left, right, outcome in comparisons:
        expectation = 1 / (1 + 10 ** ((ratings[right] - ratings[left]) / 400))
        change = elo_k * (outcome - expectation)
        ratings[left] += change
        ratings[right] -= change
    return {
        "scores": {key: {"raw_mean": mean(scores[key]), "elo": ratings[key], "appearances": len(scores[key])} for key in samples},
        "pairwise_comparisons": len(comparisons), "batches": len(schedule),
        "elo_initial": 1000, "elo_scale": 400, "elo_k": elo_k, "seed": seed,
    }


def ngrams(text: str, n: int = 13) -> frozenset[tuple[str, ...]]:
    words = text.lower().split()
    if n < 1:
        raise ValueError("ngram size must be positive")
    return frozenset(tuple(words[index : index + n]) for index in range(len(words) - n + 1))


def contamination_overlap(sample: str, heldout_texts: Sequence[str], *, n: int = 13) -> bool:
    """Exact normalized word n-gram overlap; reference text stays in curator only.

    This is not a claim to reproduce the paper's unspecified full Jaccard
    threshold, nor proof that short examples are uncontaminated.
    """
    sample_grams = ngrams(sample, n)
    return any(sample_grams.intersection(ngrams(reference, n)) for reference in heldout_texts)

