"""Activation Model Scanner math/extraction, diagnostic not a safety verdict.

§IV Eq.1–2 and official extractor use population variances with pooled scale
sqrt((var+ + var-)/2). The paper prose's printed /2 placement differs; the
implementation convention is explicit in every result. No generation occurs.
"""
from __future__ import annotations

from dataclasses import dataclass
import math

import torch
from torch import Tensor
from torch.nn import functional as F

SCALE_CONVENTION = "upstream_population_sqrt_mean_variance"


@dataclass(frozen=True)
class ConceptFingerprint:
    layer: int
    direction: Tensor
    separation: float
    pairs: int


def activation_direction(positive: Tensor, negative: Tensor) -> tuple[Tensor, Tensor]:
    if positive.ndim != 2 or positive.shape != negative.shape or len(positive) < 2:
        raise ValueError("at least two aligned contrastive activations required")
    if not torch.isfinite(positive).all() or not torch.isfinite(negative).all():
        raise ValueError("finite activations required")
    positive, negative = positive.double(), negative.double()
    delta = positive.mean(0) - negative.mean(0)
    norm = delta.norm()
    if norm <= 1e-12:
        return torch.zeros_like(delta), norm
    direction = delta / norm
    p, n = positive @ direction, negative @ direction
    pooled = ((p.var(correction=0) + n.var(correction=0)) / 2).sqrt()
    # A constant projection does not justify an infinite confidence claim.
    # Upstream uses 1.0 for this degenerate denominator, preserved explicitly.
    if pooled < 1e-8:
        pooled = pooled.new_tensor(1.)
    return direction, (p.mean() - n.mean()) / pooled


def candidate_layers(number_of_layers: int) -> tuple[int, ...]:
    if number_of_layers < 2:
        raise ValueError("at least two transformer layers required")
    # Official extractor hooks zero-based blocks in an upper-exclusive range.
    # These are block IDs, not HuggingFace hidden-state tuple indices.
    return tuple(range(int(number_of_layers * .4), int(number_of_layers * .8)))


def select_concept_layer(positive: Tensor, negative: Tensor, layer_ids: tuple[int, ...]) -> ConceptFingerprint:
    if positive.ndim != 3 or positive.shape != negative.shape or positive.shape[1] != len(layer_ids):
        raise ValueError("activation arrays must be [pair,layer,width]")
    if not layer_ids or len(set(layer_ids)) != len(layer_ids):
        raise ValueError("nonempty unique layer identities required")
    candidates = []
    for index, layer in enumerate(layer_ids):
        direction, separation = activation_direction(positive[:, index], negative[:, index])
        candidates.append(ConceptFingerprint(layer, direction, float(separation), len(positive)))
    return max(candidates, key=lambda row: row.separation)


def tier_one(fingerprints: dict[str, ConceptFingerprint]) -> str:
    if not fingerprints or any(not math.isfinite(row.separation) for row in fingerprints.values()):
        raise ValueError("nonempty finite fingerprints required")
    minimum = min(row.separation for row in fingerprints.values())
    return "PASS" if minimum > 3.5 else "CRITICAL" if minimum < 2 else "WARNING"


def compare_fingerprints(candidate: ConceptFingerprint, baseline: ConceptFingerprint) -> dict[str, float | bool]:
    if candidate.layer != baseline.layer or candidate.direction.shape != baseline.direction.shape:
        raise ValueError("Tier 2 requires the same layer and representation dimension")
    cosine = float(F.cosine_similarity(candidate.direction, baseline.direction, dim=0))
    drift = abs(candidate.separation - baseline.separation) / abs(baseline.separation) if baseline.separation else None
    return {"direction_cosine": cosine, "relative_separation_drift": drift,
            "verified": drift is not None and cosine > .8 and drift < .2}


@torch.no_grad()
def extract_last_token_activations(model, tokenizer, prompts: list[str], *, device: str,
                                   max_tokens: int = 96) -> tuple[Tensor, tuple[int, ...]]:
    if not prompts or any(not isinstance(p, str) or not p for p in prompts):
        raise ValueError("nonempty prompts required")
    layers = candidate_layers(model.config.num_hidden_layers)
    rows = []
    for prompt in prompts:
        encoded = tokenizer(prompt, return_tensors="pt", add_special_tokens=True)
        if encoded["input_ids"].numel() > max_tokens:
            raise ValueError("prompt exceeds explicit token budget; no silent truncation")
        encoded = {key: value.to(device) for key, value in encoded.items()}
        result = model(**encoded, output_hidden_states=True, use_cache=False)
        # hidden_states[0] is the input embedding; block i's output is i+1.
        # The selected range excludes the final block, whose hidden-state tuple
        # entry can additionally include the architecture's final layer norm.
        rows.append(torch.stack([result.hidden_states[layer + 1][0, -1].float() for layer in layers]))
    return torch.stack(rows), layers

"""ME-POIs Eq.9–17 loss core, not a trajectory/Maps capability reproduction.

The visit Transformer, Space2Vec and upstream private data are deliberately not
replaced by a proxy encoder. Callers supply contextual visit vectors and text
features; the runner's generated tensors are formula/gradient diagnostics only.
"""
from __future__ import annotations

import torch
from torch import Tensor, nn
from torch.nn import functional as F


def _finite(value: Tensor, name: str) -> None:
    if not torch.isfinite(value).all():
        raise ValueError(f"{name} must be finite")


def transferred_visit_distribution(
    sparse_xy: Tensor, anchor_xy: Tensor, anchor_histograms: Tensor, bandwidths: Tensor
) -> Tensor:
    """Eq.10–11: separately normalize each Gaussian scale, then average.

    Coordinates and bandwidths must use the same projected-distance unit.
    Histogram counts are normalized here; zero-count anchors are rejected.
    """
    if sparse_xy.ndim != 2 or sparse_xy.shape[1] != 2 or anchor_xy.ndim != 2 or anchor_xy.shape[1] != 2:
        raise ValueError("coordinates must have shape [POI, 2]")
    if anchor_histograms.ndim != 2 or anchor_histograms.shape[0] != len(anchor_xy) or not len(anchor_xy):
        raise ValueError("nonempty anchor histograms must align with coordinates")
    if bandwidths.ndim != 1 or not bandwidths.numel() or (bandwidths <= 0).any():
        raise ValueError("bandwidths must be a positive nonempty vector")
    for value, name in ((sparse_xy, "coordinates"), (anchor_xy, "coordinates"),
                        (anchor_histograms, "histograms"), (bandwidths, "bandwidths")):
        _finite(value, name)
    if (anchor_histograms < 0).any() or (anchor_histograms.sum(-1) <= 0).any():
        raise ValueError("anchor histograms must have nonnegative positive total counts")
    hist = anchor_histograms / anchor_histograms.sum(-1, keepdim=True)
    distances = (sparse_xy[:, None] - anchor_xy[None]).square().sum(-1)
    weights = (-distances[None] / (2 * bandwidths[:, None, None].square())).softmax(-1)
    return (weights @ hist).mean(0)


def prototype_contrastive_loss(visits: Tensor, prototypes: Tensor, poi_ids: Tensor, temperature: float = .1) -> Tensor:
    """Eq.9 with unique minibatch POI prototypes, not duplicate visit negatives."""
    if visits.ndim != 2 or prototypes.ndim != 2 or visits.shape[1] != prototypes.shape[1]:
        raise ValueError("visit/prototype dimensions must agree")
    if poi_ids.shape != (len(visits),) or poi_ids.dtype != torch.long or not len(visits):
        raise ValueError("one integer POI identity required per nonempty visit")
    if temperature <= 0 or not torch.isfinite(torch.tensor(temperature)):
        raise ValueError("temperature must be positive finite")
    if (poi_ids < 0).any() or (poi_ids >= len(prototypes)).any():
        raise ValueError("POI identity outside prototype table")
    _finite(visits, "visits")
    _finite(prototypes, "prototypes")
    unique, target = torch.unique(poi_ids, sorted=True, return_inverse=True)
    logits = F.normalize(visits, dim=-1) @ F.normalize(prototypes[unique], dim=-1).T / temperature
    return F.cross_entropy(logits, target)


def distribution_kl_sum(logits: Tensor, target: Tensor) -> Tensor:
    """Eq.13/15 sum over POIs, including zero-probability target bins."""
    if logits.shape != target.shape or logits.ndim != 2:
        raise ValueError("logits and target must align as [POI, time-bin]")
    _finite(logits, "logits")
    _finite(target, "target")
    if (target < 0).any() or not torch.allclose(target.sum(-1), torch.ones_like(target.sum(-1)), atol=1e-5):
        raise ValueError("target rows must be distributions")
    return F.kl_div(logits.log_softmax(-1), target, reduction="sum")


class MobilityPrototypeLoss(nn.Module):
    """Trainable prototypes, shared temporal MLP and projected-text alignment."""

    def __init__(self, pois: int, dim: int, text_dim: int, bins: int):
        super().__init__()
        if min(pois, dim, text_dim, bins) <= 0:
            raise ValueError("all dimensions must be positive")
        self.prototypes = nn.Parameter(torch.empty(pois, dim))
        nn.init.normal_(self.prototypes, std=.02)
        self.temporal = nn.Sequential(nn.Linear(dim, dim), nn.ReLU(), nn.Linear(dim, bins))
        self.text_projection = nn.Linear(text_dim, dim, bias=False)

    def forward(self, visits: Tensor, poi_ids: Tensor, text_features: Tensor,
                anchor_ids: Tensor, anchor_distribution: Tensor, sparse_ids: Tensor,
                sparse_prior: Tensor, weights: tuple[float, float, float] = (1., 1., 1.)) -> dict[str, Tensor]:
        if text_features.ndim != 2 or len(text_features) != len(self.prototypes):
            raise ValueError("text features must cover every prototype")
        if any(weight < 0 or not torch.isfinite(torch.tensor(weight)) for weight in weights):
            raise ValueError("loss weights must be nonnegative finite")
        ids = torch.cat((anchor_ids, sparse_ids))
        if ids.dtype != torch.long or (ids < 0).any() or (ids >= len(self.prototypes)).any():
            raise ValueError("anchor/sparse identity outside prototype table")
        if len(torch.unique(ids)) != len(ids):
            raise ValueError("anchor and sparse identities must be disjoint and unique")
        _finite(text_features, "text")
        contrastive = prototype_contrastive_loss(visits, self.prototypes, poi_ids)
        logits = self.temporal(self.prototypes)
        anchor = distribution_kl_sum(logits[anchor_ids], anchor_distribution)
        sparse = distribution_kl_sum(logits[sparse_ids], sparse_prior.detach())
        text = (1 - F.cosine_similarity(self.prototypes, self.text_projection(text_features.detach()), dim=-1)).sum()
        total = contrastive + weights[0] * anchor + weights[1] * sparse + weights[2] * text
        return {"loss": total, "contrastive": contrastive, "anchor_kl": anchor,
                "sparse_kl": sparse, "text_alignment": text}

"""Finite-support robust generative gate: paper §5.2, §6 and §7.3.

Exact finite sums expose the global partition constraint instead of pretending
that an input-wise softmax over experts normalizes the resulting sequence law.
No language-model robustness/capability claim follows from these diagnostics.
"""
from __future__ import annotations

import torch
from torch import Tensor


def _distributions(value: Tensor, name: str) -> None:
    if value.ndim != 2 or not value.numel() or not torch.isfinite(value).all() or (value <= 0).any():
        raise ValueError(f"{name} must be positive finite [domain, support]")
    if not torch.allclose(value.sum(-1), torch.ones_like(value.sum(-1)), atol=1e-6):
        raise ValueError(f"{name} rows must sum to one")


def gated_mass(experts: Tensor, gate_logits: Tensor) -> Tensor:
    """π_g(x)=Σ_k g(x,k)π_k(x); this is NOT automatically a probability law."""
    _distributions(experts, "experts")
    if gate_logits.shape != experts.T.shape or not torch.isfinite(gate_logits).all():
        raise ValueError("gate logits must be finite [support, expert]")
    return (gate_logits.softmax(-1) * experts.T.detach()).sum(-1)


def primal_dual_step(gate_logits: Tensor, experts: Tensor, domains: Tensor,
                     adversary: Tensor, dual: Tensor, optimizer: torch.optim.Optimizer,
                     *, adversary_lr: float = .05, dual_lr: float = .1,
                     adversary_objective: str = "nll") -> dict[str, Tensor]:
    """Algorithm 2's practical NLL game with exact-support normalization.

    §5.2/Appendix D Algorithm 6 use domain NLL for the adversary. The theory's
    Algorithm 1 uses KL; they differ by each domain's entropy and are NOT the
    same adversary game. Explicit objective="kl" supports that mathematical
    comparison, not an undocumented replacement of the practical algorithm.
    """
    _distributions(domains, "domains")
    if domains.shape != experts.shape or adversary.shape != (len(domains),) or dual.numel() != 1:
        raise ValueError("domain, adversary and dual dimensions must align")
    if (adversary <= 0).any() or not torch.isfinite(adversary).all() or not torch.isfinite(dual).all():
        raise ValueError("adversary must be positive and dual finite")
    if not torch.allclose(adversary.sum(), adversary.new_tensor(1.)) or min(adversary_lr, dual_lr) <= 0:
        raise ValueError("normalized adversary and positive learning rates required")
    if adversary_objective not in ("nll", "kl"):
        raise ValueError("adversary objective must be nll or kl")
    mass = gated_mass(experts, gate_logits)
    domain_nll = -(domains * mass.log()[None]).sum(-1)
    domain_kl = (domains * (domains.log() - mass.log()[None])).sum(-1)
    gains = domain_nll if adversary_objective == "nll" else domain_kl
    updated = (adversary.log() + adversary_lr * gains.detach()).softmax(-1)
    new_dual = dual.detach() + dual_lr * (mass.sum().detach() - 1)
    objective = (updated * gains).sum() + new_dual * (mass.sum() - 1)
    optimizer.zero_grad()
    objective.backward()
    optimizer.step()
    return {"adversary": updated.detach(), "dual": new_dual.detach(),
            "domain_kl": domain_kl.detach(), "domain_nll": domain_nll.detach(),
            "partition": mass.sum().detach(),
            "objective": objective.detach()}


def sir_resample(experts: Tensor, gate_logits: Tensor, candidates: int, samples: int,
                 generator: torch.Generator) -> Tensor:
    """Algorithm 3 finite-support SIR; invalid/zero mass is an error, not success."""
    if min(candidates, samples) <= 0:
        raise ValueError("positive sampling budgets required")
    mass = gated_mass(experts, gate_logits).detach()
    proposal = experts.mean(0)
    output = []
    for _ in range(samples):
        proposed = torch.multinomial(proposal, candidates, replacement=True, generator=generator)
        weights = mass[proposed] / proposal[proposed]
        choice = torch.multinomial(weights, 1, generator=generator)
        output.append(proposed[choice].reshape(()))
    return torch.stack(output)


def cached_router_nll(router_logits: Tensor, cached_target_log_probs: Tensor, mask: Tensor | None = None) -> Tensor:
    """Algorithm 5: NLL of observed teacher tokens under a causal expert router.

    Cached tensor stores log π_k(y_t|prefix), not full teacher distributions;
    detached expert probabilities cannot receive training gradients. Causality
    is the caller's contract: logits must be computed from prefixes only.
    """
    if router_logits.shape != cached_target_log_probs.shape or router_logits.ndim != 3:
        raise ValueError("router and cached target log probabilities must be [batch,time,expert]")
    if not torch.isfinite(router_logits).all() or not torch.isfinite(cached_target_log_probs).all():
        raise ValueError("finite log probabilities required")
    if (cached_target_log_probs > 1e-6).any():
        raise ValueError("cached target log probabilities cannot be positive")
    nll = -torch.logsumexp(router_logits.log_softmax(-1) + cached_target_log_probs.detach(), -1)
    if mask is None:
        return nll.mean()
    if mask.shape != nll.shape or mask.dtype != torch.bool or not mask.any():
        raise ValueError("mask must be nonempty boolean [batch,time]")
    return nll[mask].mean()

