    kind: str


@dataclass(frozen=True)
class CodeGraph:
    nodes: tuple[Node, ...]
    edges: tuple[Edge, ...]
    source_sha256: str
    unresolved_dependencies: tuple[Edge, ...] = ()
    parser: str = "python-stdlib-ast-not-tree-sitter"

    def skeleton(self) -> str:
        return json.dumps({"parser": self.parser, "source_sha256": self.source_sha256,
                           "nodes": [asdict(n) for n in self.nodes],
                           "edges": [asdict(e) for e in self.edges],
                           "unresolved_dependencies": [asdict(e) for e in self.unresolved_dependencies]},
                          sort_keys=True, separators=(",", ":"))

    def retrieve(self, target: str, *, hops: int = 3) -> tuple[Node, ...]:
        """Outgoing dependency neighborhood, with explicit maximum of three hops."""
        lookup = {n.key: n for n in self.nodes}
        if target not in lookup or not 0 <= hops <= 3:
            raise ValueError("known target and 0..3 hop limit required")
        seen, pending = {target}, deque([(target, 0)])
        while pending:
            key, depth = pending.popleft()
            if depth == hops:
                continue
            for edge in self.edges:
                if edge.source == key and edge.target not in seen:
                    seen.add(edge.target)
                    pending.append((edge.target, depth + 1))
        return tuple(lookup[key] for key in sorted(seen))


def _identifier(expression: ast.expr) -> str | None:
    if isinstance(expression, ast.Name):
        return expression.id
    if isinstance(expression, ast.Attribute):
        parent = _identifier(expression.value)
        return f"{parent}.{expression.attr}" if parent else None
    return None


def extract_python_graph(sources: Mapping[str, str]) -> CodeGraph:
    """Input keys are explicit module names; never executes or imports source code."""
    if not sources or len(sources) > 64 or any(len(v) > 100000 for v in sources.values()):
        raise ValueError("bounded nonempty source mapping required")
    trees = {module: ast.parse(text) for module, text in sources.items()}
    nodes: dict[str, Node] = {}
    objects: dict[str, ast.AST] = {}
    aliases: dict[str, dict[str, str]] = {}
    for module, tree in sorted(trees.items()):
        aliases[module] = {}
        for item in tree.body:
            if isinstance(item, (ast.Import, ast.ImportFrom)):
                for alias in item.names:
                    origin = (f"{item.module}.{alias.name}" if isinstance(item, ast.ImportFrom)
                              and item.module else alias.name)
                    aliases[module][alias.asname or alias.name.split(".")[0]] = origin
            if isinstance(item, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
                key = f"{module}.{item.name}"
                if key in nodes:
                    raise ValueError("duplicate top-level symbol")
                kind = "class" if isinstance(item, ast.ClassDef) else "function"
                signature = item.name if kind == "class" else ast.unparse(item.args)
                nodes[key] = Node(key, kind, module, signature)
                objects[key] = item
    def resolve(module, name, shadow=frozenset()):
        head, _, tail = name.partition(".")
        if head in shadow:
            return None
        alias = aliases[module].get(head)
        rewritten = alias + ("." + tail if tail else "") if alias else name
        if rewritten in nodes:
            return rewritten
        local = f"{module}.{rewritten}"
        if local in nodes:
            return local
        # Unimported global short names are not repository-wide symbols. Guessing
        # here silently connects unrelated modules and corrupts dependency order.
        return None

    def call_targets(item):
        collected = []
        references = []

        def bindings(function):
            names = {a.arg for a in (list(function.args.posonlyargs) + list(function.args.args)
                                    + list(function.args.kwonlyargs))}
            names.update(a.arg for a in (function.args.vararg, function.args.kwarg) if a)

            class Bindings(ast.NodeVisitor):
                def visit_Name(self, node):
                    if isinstance(node.ctx, ast.Store):
                        names.add(node.id)

                def visit_FunctionDef(self, node):
                    names.add(node.name)

                visit_AsyncFunctionDef = visit_FunctionDef

                def visit_ClassDef(self, node):
                    names.add(node.name)

                def visit_Import(self, node):
                    names.update(a.asname or a.name.split(".")[0] for a in node.names)

                def visit_ImportFrom(self, node):
                    names.update(a.asname or a.name for a in node.names)

            visitor = Bindings()
            for statement in function.body:
                visitor.visit(statement)
            return names

        class Calls(ast.NodeVisitor):
            def __init__(self):
                self.shadow = set()

            def visit_FunctionDef(self, node):
                previous = self.shadow
                self.shadow = previous | bindings(node)
                for statement in node.body:
                    self.visit(statement)
                self.shadow = previous

            visit_AsyncFunctionDef = visit_FunctionDef

            def visit_Call(self, node):
                collected.append((node, frozenset(self.shadow)))
                self.generic_visit(node)

            def visit_Name(self, node):
                if isinstance(node.ctx, ast.Load):
                    references.append((node.id, frozenset(self.shadow)))

        Calls().visit(item)
        return collected, references

    edges: set[Edge] = set()
    unresolved: set[Edge] = set()
    for key, item in objects.items():
        module = nodes[key].module
        if isinstance(item, ast.ClassDef):
            for base in item.bases:
                identifier = _identifier(base)
                target = resolve(module, identifier) if identifier else None
                if target:
                    edges.add(Edge(key, target, "INHERITS"))
                else:
                    unresolved.add(Edge(key, identifier or ast.unparse(base), "INHERITS"))
            for member in item.body:
                if isinstance(member, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    # Signatures are retained in the architecture skeleton, not executable bodies.
                    method_key = f"{key}.{member.name}"
                    nodes[method_key] = Node(method_key, "method", module, ast.unparse(member.args))
        calls, references = call_targets(item)
        for statement, shadow in calls:
            identifier = _identifier(statement.func)
            target = resolve(module, identifier, shadow) if identifier else None
            if target:
                edges.add(Edge(key, target, "CALLS"))
            else:
                unresolved.add(Edge(key, identifier or ast.unparse(statement.func), "CALLS"))
        for local_name, imported in aliases[module].items():
            if any(name == local_name and name not in shadow for name, shadow in references):
                target = resolve(module, imported)
                if target:
                    edges.add(Edge(key, target, "IMPORTS"))
                else:
                    unresolved.add(Edge(key, imported, "IMPORTS"))
    fingerprint = hashlib.sha256(json.dumps(dict(sources), sort_keys=True,
                                            separators=(",", ":")).encode()).hexdigest()
    return CodeGraph(tuple(sorted(nodes.values())), tuple(sorted(edges)), fingerprint,
                     tuple(sorted(unresolved)))


def dependency_order(graph: CodeGraph) -> tuple[tuple[str, ...], ...]:
    """SCC condensation: each dependency group precedes consumers, cycles explicit.

    The paper does not specify its cycle breaker. We retain SCC groups rather
    than inventing a valid within-cycle parent order or silently dropping edges.
    """
    keys = {n.key for n in graph.nodes if n.kind != "method"}
    deps = {k: set() for k in keys}
    for edge in graph.edges:
        if edge.source in keys and edge.target in keys:
            deps[edge.source].add(edge.target)
    index, stack, indices, low, on_stack, groups = 0, [], {}, {}, set(), []

    def visit(key):
        nonlocal index
        indices[key] = low[key] = index
        index += 1
        stack.append(key)
        on_stack.add(key)
        for dependency in sorted(deps[key]):
            if dependency not in indices:
                visit(dependency)
                low[key] = min(low[key], low[dependency])
            elif dependency in on_stack:
                low[key] = min(low[key], indices[dependency])
        if low[key] == indices[key]:
            component = []
            while True:
                node = stack.pop()
                on_stack.remove(node)
                component.append(node)
                if node == key:
                    break
            groups.append(tuple(sorted(component)))

    for key in sorted(keys):
        if key not in indices:
            visit(key)
    return tuple(groups)


class SkeletonCache:
    """Local content-keyed one-hour cache; NOT Vertex AI context caching."""
    def __init__(self, clock: Callable[[], float] = time.monotonic):
        self.clock, self.entries = clock, {}

    def get(self, graph: CodeGraph) -> str:
        now = self.clock()
        old = self.entries.get(graph.source_sha256)
        if old is None or now - old[0] >= 3600:
            old = (now, graph.skeleton())
            self.entries[graph.source_sha256] = old
        return old[1]


def static_metrics(source_python: str, migrated_python: str, *,
                   allowed_imports: frozenset[str] = frozenset()) -> dict:
    """Explicit subset of paper metrics, no CodeBLEU/MQ/pyflakes/Java claims."""
    reference = ast.parse(source_python)
    try:
        target = ast.parse(migrated_python)
    except SyntaxError:
        return {"syntax_parse": False, "pcc": None, "thc": None, "drq": None,
                "docstring_preservation": None}
    source_classes = {n.name: {_identifier(b) for b in n.bases}
                      for n in ast.walk(reference) if isinstance(n, ast.ClassDef)}
    target_classes = {n.name: {_identifier(b) for b in n.bases}
                      for n in ast.walk(target) if isinstance(n, ast.ClassDef)}
    pcc = (sum(target_classes.get(name) == bases for name, bases in source_classes.items()) /
           len(source_classes)) if source_classes else None
    functions = [n for n in ast.walk(target) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))]
    typed = []
    for function in functions:
        args = list(function.args.posonlyargs) + list(function.args.args) + list(function.args.kwonlyargs)
        args += [x for x in (function.args.vararg, function.args.kwarg) if x]
        typed.append(all(a.annotation is not None for a in args if a.arg not in {"self", "cls"})
                     and function.returns is not None)
    imported = []
    for node in ast.walk(target):
        if isinstance(node, ast.Import):
            imported.extend(a.name.split(".")[0] for a in node.names)
        elif isinstance(node, ast.ImportFrom):
            imported.append((node.module or "").split(".")[0])
    available = set(sys.stdlib_module_names) | set(allowed_imports)
    drq = sum(name in available for name in imported) / len(imported) if imported else None

    def docs(tree):
        return {n.name for n in ast.walk(tree)
                if isinstance(n, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef))
                and ast.get_docstring(n)}

    originals = docs(reference)
    return {"syntax_parse": True, "pcc": pcc,
            "thc": sum(typed) / len(typed) if typed else None,
            "drq": drq,
            "docstring_preservation": len(originals & docs(target)) / len(originals)
            if originals else None}

"""POLCA priority/history/epsilon-net core; no implicit LLM or benchmark oracle.

Implements paper Algorithm 1 and farthest-first filter from the linked author
implementation. Summarizer, proposer, embedding and evaluator are real callback
interfaces; unit fixtures are not evidence of model optimization capability.
"""
from __future__ import annotations

from copy import deepcopy
from dataclasses import dataclass
import math
import random
from typing import Callable, Sequence

PROTOCOL = "polca-empirical-queue-epsilon-net-component-v1"
UPSTREAM_COMMIT = "4ee52f12f0bb328dfee2f16b6c1801232c6ccf46"


@dataclass(frozen=True)
class Candidate:
    key: str
    parameter: str
    embedding: tuple[float, ...]

    def __post_init__(self):
        if not self.key or not self.parameter or not self.embedding:
            raise ValueError("candidate identity, parameter and embedding required")
        if any(not math.isfinite(x) for x in self.embedding):
            raise ValueError("finite embedding required")


@dataclass(frozen=True)
class EvaluationResult:
    score: float
    feedback: str
    output: object


@dataclass(frozen=True)
class Observation:
    candidate_key: str
    item_id: str
    input: object
    output: object
    score: float
    feedback: str
    round_index: int


@dataclass(frozen=True)
class History:
    candidate: Candidate
    observations: tuple[Observation, ...]

    @property
    def mean(self) -> float:
        return sum(x.score for x in self.observations) / len(self.observations)

    @property
    def sample_variance(self) -> float | None:
        n = len(self.observations)
        return None if n < 2 else sum((x.score - self.mean) ** 2 for x in self.observations) / (n - 1)


def epsilon_filter(proposals: Sequence[Candidate], memory: Sequence[Candidate], *,
                   epsilon: float) -> tuple[Candidate, ...]:
    """Greedy farthest-to-current-memory first, strict distance > epsilon.

    The epsilon=0 path follows the author's explicit no-filter ablation; duplicate
    identities still fail rather than corrupting the statistics dictionary.
    """
    if not math.isfinite(epsilon) or epsilon < 0:
        raise ValueError("nonnegative finite epsilon required")
    all_candidates = tuple(memory) + tuple(proposals)
    if len({p.key for p in all_candidates}) != len(all_candidates):
        raise ValueError("candidate identities must be unique")
    dimensions = {len(p.embedding) for p in all_candidates}
    if len(dimensions) > 1:
        raise ValueError("consistent embedding dimension required")
    if epsilon == 0:
        return tuple(proposals)
    remaining, accepted, existing = list(proposals), [], list(memory)
    while remaining:
        distances = [min((math.dist(p.embedding, q.embedding) for q in existing),
                         default=math.inf) for p in remaining]
        index = max(range(len(remaining)), key=lambda i: (distances[i], -i))
        if distances[index] <= epsilon:
            break
        candidate = remaining.pop(index)
        accepted.append(candidate)
        existing.append(candidate)
    return tuple(accepted)


@dataclass(frozen=True)
class RoundTrace:
    round_index: int
    minibatch_ids: tuple[str, ...]
    selected: tuple[str, ...]
    proposed: tuple[str, ...]
    admitted: tuple[str, ...]
    deferred_budget: tuple[str, ...]
    summary: str
    metric_calls: int


class Polca:
    """Small synchronous bounded controller; never receives a test split.

    Minibatches are sampled with replacement. Repeated evaluations of promising
    programs update their empirical means/variance instead of keeping best-of-N
    noisy observations. This is paper §3 priority, not the theoretical UCB variant.
    """
    def __init__(self, initial: Candidate, *, epsilon: float, seed: int = 42,
                 max_metric_calls: int = 64, max_memory: int = 16):
        if not math.isfinite(epsilon) or epsilon < 0:
            raise ValueError("finite nonnegative epsilon required")
        if not 1 <= max_metric_calls <= 1000 or not 1 <= max_memory <= 128:
            raise ValueError("bounded metric/memory budgets required")
        self.epsilon, self.rng = epsilon, random.Random(seed)
        self.max_metric_calls, self.max_memory = max_metric_calls, max_memory
        self.memory = {initial.key: History(initial, ())}
        self.calls, self.traces = 0, []

    def histories(self) -> tuple[History, ...]:
        return tuple(self.memory.values())

    def _record(self, candidate, batch, evaluator, round_index):
        old = self.memory.get(candidate.key, History(candidate, ()))
        for item_id, value in batch:
            # Count before invocation so failures never silently restore a spent call.
            self.calls += 1
            observed_input = deepcopy(value)
            result = evaluator(candidate, value)
            if (not isinstance(result, EvaluationResult) or not math.isfinite(result.score)
                    or not isinstance(result.feedback, str)):
                raise ValueError("EvaluationResult with finite score, feedback and actual output required")
            observation = Observation(candidate.key, item_id, observed_input,
                                      deepcopy(result.output), result.score, result.feedback, round_index)
            old = History(candidate, old.observations + (observation,))
            self.memory[candidate.key] = old

    def round(self, validation: Sequence[tuple[str, object]], *,
              evaluator: Callable[[Candidate, object], EvaluationResult],
              summarizer: Callable[[tuple[History, ...]], str],
              proposer: Callable[[tuple[History, ...], str], Sequence[Candidate]],
              batch_size: int = 2, select_count: int = 1,
              split: str = "validation") -> RoundTrace:
        if split != "validation" or not validation or not 1 <= batch_size <= 16:
            raise ValueError("nonempty validation-only dataset and bounded batch required")
        if len({key for key, _ in validation}) != len(validation):
            raise ValueError("unique validation item IDs required")
        if not 1 <= select_count <= len(self.memory):
            raise ValueError("valid exploration count required")
        if self.calls + batch_size * select_count > self.max_metric_calls:
            raise RuntimeError("insufficient metric budget for an exploration minibatch")
        round_index = len(self.traces)
        batch = tuple(self.rng.choice(validation) for _ in range(batch_size))
        selected = sorted(self.histories(), key=lambda h: (
            -(h.mean if h.observations else math.inf), h.candidate.key))[:select_count]
        for history in selected:
            self._record(history.candidate, batch, evaluator, round_index)
        history = self.histories()
        summary = summarizer(history)
        if not isinstance(summary, str) or len(summary) > 24000:
            raise ValueError("bounded real summarizer response required")
        selected_history = tuple(self.memory[h.candidate.key] for h in selected)
        raw = tuple(proposer(selected_history, summary))
        if len(raw) > 16:
            raise ValueError("proposal budget exceeded")
        admitted = epsilon_filter(raw, [h.candidate for h in history], epsilon=self.epsilon)
        accepted, deferred = [], []
        for candidate in admitted:
            if (len(self.memory) >= self.max_memory or
                    self.calls + batch_size > self.max_metric_calls):
                deferred.append(candidate.key)
                continue
            # Identical sampled batch for old and new candidates, not a lucky resample.
            self._record(candidate, batch, evaluator, round_index)
            accepted.append(candidate.key)
        trace = RoundTrace(round_index, tuple(key for key, _ in batch),
                           tuple(h.candidate.key for h in selected), tuple(c.key for c in raw),
                           tuple(accepted), tuple(deferred), summary, self.calls)
        self.traces.append(trace)
        return trace

    def best(self) -> History:
        evaluated = [h for h in self.histories() if h.observations]
        if not evaluated:
            raise RuntimeError("no observed candidate")
        return min(evaluated, key=lambda h: (-h.mean, h.candidate.key))
